 * Implements Separation, Alignment, Cohesion, and Obstacle Avoidance.
 */

// --- 1. GLOBAL MATH UTILITIES ---
const limit = (v, max) =&gt; {
    const mag = Math.hypot(v.x, v.y);
    if (mag &gt; max) {
        v.x = (v.x / mag) * max;
        v.y = (v.y / mag) * max;
    }
};

const setMag = (v, mag) =&gt; {
    const curr = Math.hypot(v.x, v.y);
    if (curr &gt; 0) {
        v.x = (v.x / curr) * mag;
        v.y = (v.y / curr) * mag;
    }
};

// --- 2. TOP-LEVEL ACTIONS ---
let boids = [];
let obstacles = [];

const initBoids = (w, h) =&gt; {
    const count = 50;
    const arr = [];
    for (let i = 0; i &lt; count; i++) {
        arr.push({
            x: Math.random() * w,
            y: Math.random() * h,
            vx: (Math.random() - 0.5) * 4,
            vy: (Math.random() - 0.5) * 4,
            ax: 0,
            ay: 0
        });
    }
    return arr;
};

const handleReset = (s) =&gt; {
    // We need current width/height, but state doesn&#39;t track it.
    // We&#39;ll flag a reset for the loop to handle.
    s._needsReset = true;
};

const handleAddObstacle = (s) =&gt; {
    s._needsObstacle = true;
};

// --- 3. APP INITIALIZATION ---
const { state, ui } = WH.createApp({
    title: &quot;Boids Flocking Simulation&quot;,
    params: {
        separation: { value: 1.5, min: 0, max: 5, step: 0.1, label: &quot;Separation&quot; },
        alignment: { value: 1.5, min: 0, max: 5, step: 0.1, label: &quot;Alignment&quot; },
        cohesion: { value: 1.5, min: 0, max: 5, step: 0.1, label: &quot;Cohesion&quot; },
        addObstacle: { type: &#39;button&#39;, label: &#39;Add Obstacle&#39;, onClick: handleAddObstacle },
        reset: { type: &#39;button&#39;, label: &#39;Reset&#39;, onClick: handleReset }
    },
    editorial: {
        hud: [
            { label: &quot;Boids&quot;, value: &quot;50&quot; },
            { label: &quot;System State&quot;, value: &quot;Active&quot; }
        ]
    }
});

// Internal triggers
state._needsReset = false;
state._needsObstacle = false;

// --- 4. ENGINE INITIALIZATION ---
WH.initCanvas(&#39;viz&#39;, ({ ctx, width, height }) =&gt; {

    // Initial setup
    boids = initBoids(width, height);
    obstacles = [];

    const PERCEPTION = 60;
    const MAX_SPEED = 3.5;
    const MAX_FORCE = 0.15;
    const BOID_SIZE = 8;

    // HUD Subscriber
    state._subscribe(&#39;boids_count&#39;, (val) =&gt; {
        ui.setEditorial({
            hud: [
                { label: &quot;Boids&quot;, value: val.toString() },
                { label: &quot;Obstacles&quot;, value: obstacles.length.toString() }
            ]
        });
    });

    // Setup legend
    ui.setLegend([
        { label: &#39;Boid&#39;, color: &#39;--primary&#39; },
        { label: &#39;Obstacle&#39;, color: &#39;--surface-container-highest&#39; }
    ]);

    return ({ dt, width, height, frameCount }) =&gt; {
        // Handle Triggered Actions
        if (state._needsReset) {
            boids = initBoids(width, height);
            obstacles = [];
            state._needsReset = false;
            state.boids_count = boids.length;
        }

        if (state._needsObstacle) {
            obstacles.push({
                x: Math.random() * (width - 100) + 50,
                y: Math.random() * (height - 100) + 50,
                r: 25 + Math.random() * 25
            });
            state._needsObstacle = false;
            state.boids_count = boids.length; // Triggers HUD update
        }

        // --- PHYSICS UPDATE ---
        for (let boid of boids) {
            let sep = { x: 0, y: 0 };
            let ali = { x: 0, y: 0 };
            let coh = { x: 0, y: 0 };
            let obs = { x: 0, y: 0 };
            let total = 0;

            for (let other of boids) {
                const d = Math.hypot(boid.x - other.x, boid.y - other.y);
                if (other !== boid &amp;&amp; d &lt; PERCEPTION) {
                    // Separation
                    const diff = { x: boid.x - other.x, y: boid.y - other.y };
                    const distSq = d * d;
                    sep.x += diff.x / distSq;
                    sep.y += diff.y / distSq;

                    // Alignment
                    ali.x += other.vx;
                    ali.y += other.vy;

                    // Cohesion
                    coh.x += other.x;
                    coh.y += other.y;

                    total++;
                }
            }

            // Finalize forces if neighbors found
            if (total &gt; 0) {
                // Alignment: steer to average velocity
                ali.x /= total; ali.y /= total;
                setMag(ali, MAX_SPEED);
                ali.x -= boid.vx; ali.y -= boid.vy;
                limit(ali, MAX_FORCE);

                // Cohesion: steer to center of mass
                coh.x /= total; coh.y /= total;
                coh.x -= boid.x; coh.y -= boid.y;
                setMag(coh, MAX_SPEED);
                coh.x -= boid.vx; coh.y -= boid.vy;
                limit(coh, MAX_FORCE);

                // Separation: steer away from crowd
                setMag(sep, MAX_SPEED);
                sep.x -= boid.vx; sep.y -= boid.vy;
                limit(sep, MAX_FORCE);
            }

            // Obstacle Avoidance
            for (let o of obstacles) {
                const d = Math.hypot(boid.x - o.x, boid.y - o.y);
                const buffer = 40;
                if (d &lt; o.r + buffer) {
                    const diff = { x: boid.x - o.x, y: boid.y - o.y };
                    setMag(diff, MAX_SPEED * 2); // Stronger urge to avoid
                    obs.x += diff.x;
                    obs.y += diff.y;
                }
            }
            limit(obs, MAX_FORCE * 3);

            // Apply weighted forces from sliders
            boid.ax = (sep.x * state.separation) + (ali.x * state.alignment) + (coh.x * state.cohesion) + obs.x;
            boid.ay = (sep.y * state.separation) + (ali.y * state.alignment) + (coh.y * state.cohesion) + obs.y;

            // Integration
            boid.vx += boid.ax;
            boid.vy += boid.ay;
            limit(boid, MAX_SPEED);

            boid.x += boid.vx;
            boid.y += boid.vy;

            // Boundary Wrapping
            if (boid.x &lt; 0) boid.x = width;
            if (boid.x &gt; width) boid.x = 0;
            if (boid.y &lt; 0) boid.y = height;
            if (boid.y &gt; height) boid.y = 0;
        }

        // --- DRAWING ---

        // 1. Draw Obstacles
        ctx.fillStyle = WH.getColor(&#39;--surface-container-highest&#39;);
        ctx.strokeStyle = WH.getColor(&#39;--stroke-emphasis&#39;);
        ctx.lineWidth = 2;
        for (let o of obstacles) {
            ctx.beginPath();
            ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();
        }

        // 2. Draw Boids
        ctx.fillStyle = WH.getColor(&#39;--primary&#39;);
        for (let boid of boids) {
            const angle = Math.atan2(boid.vy, boid.vx);

            ctx.save();
            ctx.translate(boid.x, boid.y);
            ctx.rotate(angle);

            ctx.beginPath();
            ctx.moveTo(BOID_SIZE, 0);
            ctx.lineTo(-BOID_SIZE / 2, BOID_SIZE / 2);
            ctx.lineTo(-BOID_SIZE / 2, -BOID_SIZE / 2);
            ctx.closePath();
            ctx.fill();

            ctx.restore();
        }
    };
});
&lt;/script&gt;

